 "content": "from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                rr, cc = q.popleft()
                comp.append((rr, cc, grid[rr][cc]))
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != bg and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            comps.append(comp)
    motif = max(comps, key=len)
    r0 = min(r for r,c,v in motif); r1 = max(r for r,c,v in motif)
    c0 = min(c for r,c,v in motif); c1 = max(c for r,c,v in motif)
    ar, ac = (r0+r1)//2, (c0+c1)//2
    offsets = [(r-ar,c-ac,v) for r,c,v in motif]
    motifset = {(r,c) for r,c,v in motif}
    out = [row[:] for row in grid]
    for comp in comps:
        if comp is motif:
            continue
        # Separate singleton marks act as locations to stamp the multicolor motif.
        for mr,mc,_ in comp:
            for dr,dc,v in offsets:
                rr,cc = mr+dr, mc+dc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = v
    return out
